import type { Readable } from 'node:stream';

/** Inclusive byte range, as in an HTTP `Range: bytes=start-end` header. */
export interface ByteRange {
  start: number;
  end: number;
}

export interface StoredObject {
  key: string;
  size: number;
}

export interface ObjectStat {
  size: number;
  modifiedAt: Date;
}

export interface SaveOptions {
  /** Abort and discard the upload once it exceeds this many bytes. */
  maxBytes?: number;
}

/**
 * Media storage backend. Keys are generated by the driver and are opaque to callers.
 * Implementations: LocalDiskDriver (now), S3/R2 (later).
 */
export interface StorageDriver {
  /** Streams `input` into storage under a new random key. */
  save(input: Readable, options?: SaveOptions): Promise<StoredObject>;
  /** Opens a stream of the whole object or of an inclusive byte range. */
  read(key: string, range?: ByteRange): Promise<Readable>;
  /** Deletes the object. Deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  /** Returns null when the object does not exist. */
  stat(key: string): Promise<ObjectStat | null>;
  /** Throws if the storage cannot currently be written to (used by readiness checks). */
  checkWritable(): Promise<void>;
}

export type StorageErrorCode = 'INVALID_KEY' | 'NOT_FOUND' | 'TOO_LARGE' | 'INVALID_RANGE';

export class StorageError extends Error {
  readonly code: StorageErrorCode;

  constructor(code: StorageErrorCode, message: string) {
    super(message);
    this.name = 'StorageError';
    this.code = code;
  }
}
